pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // Restrict to admissible domain: recipient is not address(c) to avoid self-destruct type issues and non-zero amount
        vm.assume(recipient != address(c));
        vm.assume(amount > 0);
        vm.assume(recipient != address(0));

        // Fund the contract
        vm.deal(address(c), amount);

        // Record balances before
        uint256 balRecipientBefore = recipient.balance;
        uint256 balContractBefore = address(c).balance;

        // Owner calls withdrawAll
        vm.prank(address(this));
        c.withdrawAll(recipient);

        // Balances after
        uint256 balRecipientAfter = recipient.balance;
        uint256 balContractAfter = address(c).balance;

        // General rule: the recipient gets exactly the amount that was in the contract, and contract balance becomes 0
        assertTrue(balRecipientAfter == balRecipientBefore + balContractBefore && balContractAfter == 0);
    }
}

